--
-- Name: hr_holidays_remaining_leaves_user; Type: VIEW; Schema: public; Owner: doadmin
--

CREATE VIEW public.hr_holidays_remaining_leaves_user AS
 SELECT min(hrs.id) AS id,
    rr.name,
    sum(hrs.number_of_days) AS no_of_leaves,
    rr.user_id,
    hhs.name AS leave_type
   FROM public.hr_holidays hrs,
    public.hr_employee hre,
    public.resource_resource rr,
    public.hr_holidays_status hhs
  WHERE ((hrs.employee_id = hre.id) AND (hre.resource_id = rr.id) AND (hhs.id = hrs.holiday_status_id))
  GROUP BY rr.name, rr.user_id, hhs.name;


