--
-- Name: hr_payroll_report_view; Type: VIEW; Schema: public; Owner: doadmin
--

CREATE VIEW public.hr_payroll_report_view AS
 SELECT min(ps.id) AS id,
    emp.id AS name,
    jb.id AS job_id,
    dp.id AS department_id,
    cmp.id AS company_id,
    ps.date_from,
    ps.date_to,
    sum(psl.total) AS net,
    ps.state
   FROM (((((public.hr_payslip_line psl
     JOIN public.hr_payslip ps ON (((ps.employee_id = psl.employee_id) AND (ps.id = psl.slip_id))))
     JOIN public.hr_employee emp ON ((ps.employee_id = emp.id)))
     JOIN public.hr_department dp ON ((emp.department_id = dp.id)))
     JOIN public.hr_job jb ON ((emp.job_id = jb.id)))
     JOIN public.res_company cmp ON ((cmp.id = ps.company_id)))
  WHERE ((psl.code)::text = 'NET'::text)
  GROUP BY emp.id, psl.total, ps.date_from, ps.date_to, ps.state, jb.id, dp.id, cmp.id;


ALTER TABLE public.hr_payroll_report_view OWNER TO doadmin;

